/**
 * Check if a persisted live session model selection is valid for restoration
 * during failover. Returns false if the target provider has all auth profiles
 * in cooldown, meaning the failover system should take precedence.
 *
 * This prevents infinite retry loops where:
 * 1. Failover switches to a backup provider (e.g., due to overload)
 * 2. resolvePersistedLiveSelection() restores the primary model selection
 * 3. The request fails again with the same error
 * 4. Failover switches back to the backup provider
 * 5. Loop repeats indefinitely
 *
 * By checking if the persisted selection's provider is in cooldown before
 * restoring it, we allow the failover decision to take precedence.
 *
 * @param params - Check parameters including config, provider, and agent directory
 * @returns true if the persisted selection is valid (not in cooldown), false otherwise
 */
export async function isLiveSessionSelectionValidForFailover(params: {
  cfg?: OpenClawConfig | undefined;
  provider: string;
  agentDir?: string;
}): Promise<boolean> {
  const { cfg, provider, agentDir } = params;

